#!/usr/bin/env python3
"""Build a self-contained review page, or validate a human-exported label file."""
import argparse
from dataclasses import asdict
import json
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'src'))
from eventlens.core import load_corpus, digest
from eventlens.review import validate_export
from earnings_review_inventory import inventory

ROOT=Path(__file__).resolve().parents[1]
LIBRARY=Path('/Users/nickzhu/Desktop/Library/AiHTMLs')


def payload():
    _,sources=load_corpus(ROOT/'data/manifest.json')
    cases=json.loads((ROOT/'data/cases.json').read_text());draft=json.loads((ROOT/'data/labels.draft.json').read_text())
    ids={c[k] for c in cases for k in ('old','new')}
    rows={}
    for case in cases:
        original=draft['cases'].get(case['case_id'],{})
        rows[case['case_id']]={'review_status':'pending','metrics':original.get('metrics',[None,None]),
                             'direction':'','explanation_status':'','explanations':[],
                             'explanation_conflict':'','notes':'','reviewed_by':None,'reviewed_at':None,
                             'human_attestation':False,'draft_origin':'Original AI draft' if original.get('metrics') else 'Blank; no machine label'}
    return {'schema':'eventlens-review-v2','source_hashes':{sid:sources[sid].content_hash for sid in sorted(ids)},
            'cases':rows,'case_metadata':cases,'sources':{sid:asdict(sources[sid]) for sid in ids},
            'windows':{r['case_id']:{side:r[side]['candidate_spans'] for side in ('old','new')} for r in inventory()['review_rows']}}


