def main():
    p=argparse.ArgumentParser();g=p.add_mutually_exclusive_group(required=True)
    g.add_argument('--build',type=Path);g.add_argument('--validate',type=Path)
    args=p.parse_args()
    if args.build:
        target=args.build.expanduser().resolve()
        if not target.is_relative_to(LIBRARY):raise ValueError('generated HTML must be under the AiHTMLs library')
        target.parent.mkdir(parents=True,exist_ok=True)
        data=json.dumps(payload(),ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
        target.write_text(PAGE.replace('__DATA__',data));print(target)
    else:
        _,sources=load_corpus(ROOT/'data/manifest.json');cases=json.loads((ROOT/'data/cases.json').read_text())
        labels=validate_export(json.loads(args.validate.read_text()),sources,cases)
        print(json.dumps({'status':labels['status'],'reviewed_pairs':sum(r['review_status']=='reviewed' for r in labels['cases'].values())}))

if __name__=='__main__':main()
